SELECT id, session_id, event_type, page, event_time, duration_sec, MAX(duration_sec) OVER (PARTITION BY page ORDER BY duration_sec ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_max_duration_sec, MIN(duration_sec) OVER (PARTITION BY page ORDER BY duration_sec ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_min_duration_sec, COUNT(duration_sec) OVER (PARTITION BY page ORDER BY duration_sec ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_count_duration_sec, SUM(duration_sec) OVER (PARTITION BY page ORDER BY duration_sec ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_sum_duration_sec, CUME_DIST() OVER (PARTITION BY page, event_type ORDER BY duration_sec DESC NULLS LAST) AS duration_sec_cume_dist FROM web_events
